```csharp
namespace example {
  enum Role {
    ADMIN = "admin",
    MEMBER = "member",
    GUEST = "guest",
  }
  resource Group {
    string id = 1;
  }
  resource Post {
    string id = 1;
    Group group = 2;
  }
  policy PostPolicy {
    // 允许管理员和成员阅读他们组中的帖子
    allow read: if(Role.ADMIN in user.roles) || (Role.MEMBER in user.roles && user.groups contains post.group.id);
    // 允许管理员在任何组中发布帖子
    allow write: if Role.ADMIN in user.roles;
    // 允许成员在自己的组中发布帖子
    allow write: if Role.MEMBER in user.roles && user.groups contains post.group.id;
  }
}
```
