接口描述语言（IDL）是用于定义软件系统之间的接口的一种语言，包括可以交换的数据类型和可以执行的操作。其中一种IDL的例子是Protocol Buffers（protobuf），是一种由Google开发的语言和平台中立的数据序列化格式。下面是如何使用protobuf来定义状态估计管理器和人机交互管理器之间接口的示例：
``` 
// 定义表示空间船状态信息的消息
message SpacecraftState {
  // 空间船在3D空间中的位置
  float x = 1;
  float y = 2;
  float z = 3;

  // 空间船的速度
  float vx = 4;
  float vy = 5;
  float vz = 6;

  // 空间船的方向
  float roll = 7;
  float pitch = 8;
  float yaw = 9;

  // 空间船子系统的健康状况和性能
  repeated SubsystemStatus subsystems = 10;
}
// 定义表示空间船子系统状态的消息
message SubsystemStatus {
  // 子系统的名称
  string name = 1;

  // 子系统的当前状态（例如，“正常”，“警告”，“关键”）
  string status = 2;

  // 关于子系统的其他信息（例如当前温度、压力等）
  repeated KeyValuePair metadata = 3;
}
// 定义表示元数据键-值对的消息
message KeyValuePair {
  string key = 1;
  string value = 2;
}
// 定义状态估计管理器和人机交互管理器之间的接口
service StateEstimationService {
  // 检索空间船的当前状态
  rpc GetSpacecraftState(GetSpacecraftStateRequest) returns (SpacecraftState);
}
// 为GetSpacecraftState RPC定义请求消息
message GetSpacecraftStateRequest {
  // 用于指定要包含在响应中的子系统的可选参数
  repeated string subsystems = 1;
}
```
这个IDL定义了状态估计管理器和人机交互管理器之间可以交换的数据类型，包括空间船的位置、速度和方向以及其子系统的状态。它还定义了一个名为“GetSpacecraftState”的RPC（远程过程调用），人机交互管理器可以使用此RPC向状态估计管理器请求空间船的当前状态。此RPC的请求消息允许人机交互管理器指定它感兴趣的子系统。

这里有一个使用 Protocol Buffers 定义技能/行为管理器和人机交互管理器之间接口的示例：

```protobuf
// 定义一个表示航天器可执行任务的消息
message Task {
  // 任务唯一标识符
  string id = 1;

  // 任务名称
  string name = 2;

  // 任务描述
  string description = 3;

  // 任务当前状态（如“待定”、“进行中”、“已完成”）
  string status = 4;

  // 任务的其他元数据（如优先级、依赖等）
  repeated KeyValuePair metadata = 5;
}

// 定义技能/行为管理器和人机交互管理器之间的接口
service SkillBehaviorService {
  // 获取航天器可执行任务列表
  rpc ListTasks(ListTasksRequest) returns (ListTasksResponse);

  // 请求航天器执行指定任务
  rpc ExecuteTask(ExecuteTaskRequest) returns (ExecuteTaskResponse);

  // 获取指定任务的状态
  rpc GetTaskStatus(GetTaskStatusRequest) returns (Task);
}

// 定义 ListTasks RPC 的请求消息
message ListTasksRequest {
  // 可选参数，用于指定响应中包括的任务类型
  repeated string types = 1;
}

// 定义 ListTasks RPC 的响应消息
message ListTasksResponse {
  // 可用任务列表
  repeated Task tasks = 1;
}

// 定义 ExecuteTask RPC 的请求消息
message ExecuteTaskRequest {
  // 要执行的任务唯一标识符
  string task_id = 1;
}

// 定义 ExecuteTask RPC 的响应消息
message ExecuteTaskResponse {
  // 任务执行后的状态（如“成功”、“失败”）
  string status = 1;
}

// 定义 GetTaskStatus RPC 的请求消息
message GetTaskStatusRequest {
  // 任务唯一标识符
  string task_id = 1;
}
```

这个接口定义了技能/行为管理器和人机交互管理器之间可交换的数据类型，包括航天器可执行任务和任务的当前状态信息。它也定义了人机交互管理器与技能/行为管理器交互的多个 RPC，包括请求可执行任务列表、请求航天器执行指定任务以及获取指定任务的状态。这些 RPC 的请求和响应消息允许人机交互管理器指定自己感兴趣的任务以及接收已执行任务的状态信息。

您说得对-在之前的示例中，我定义了一个名为`KeyValuePair`的消息类型，但没有为其提供完整的定义。这是 `KeyValuePair` 消息类型的完整定义：

```
// Define a message for representing a key-value pair of metadata
message KeyValuePair {
  string key = 1;
  string value = 2;
}
```

此消息类型表示一个简单的元数据键值对，具有字符串键和字符串值。它可以用于在认知代理中存储有关任务、子系统或其他数据类型的其他信息。

