```
syntax = "proto3";
package psm;
message Goal {
  string name = 1;
  string description = 2;
  float priority = 3;
  bool achieved = 4;
}
message Constraint {
  string name = 1;
  string description = 2;
  bool satisfied = 3;
}
message Plan {
  repeated Goal goals = 1;
  repeated Constraint constraints = 2;
  string description = 3;
  bool feasible = 4;
  bool executable = 5;
}
message Schedule {
  repeated Plan plans = 1;
  string description = 2;
}
service Planner {
  rpc CreatePlan(Goal) returns (Plan) {}
  rpc UpdatePlan(Plan) returns (Plan) {}
  rpc DeletePlan(Plan) returns (empty) {}
  rpc GetPlans() returns (repeated Plan) {}
  rpc CreateSchedule(Plan) returns (Schedule) {}
  rpc UpdateSchedule(Schedule) returns (Schedule) {}
  rpc DeleteSchedule(Schedule) returns (empty) {}
  rpc GetSchedules() returns (repeated Schedule) {}
}
```
该IDL定义了在PSM中表示目标、约束、计划和时间表的消息，以及用于创建、更新和删除这些实体以及检索它们的列表的服务。“Goal”消息包括目标名称和描述、优先级以及指示其是否已实现的标志字段。“Constraint”消息包括类似的名称、描述和满足条件的字段。

