```
public class DataObjectMapper {
    private Map<String，Interpreter> 解释器;
    public DataObjectMapper() {
        这.interpreters = new HashMap<>();
    }
    public void registerInterpreter(String attribute，Interpreter interpreter) {
        这.interpreters.put(attribute，interpreter);
    }
    public DataObject map(DataObject source) {
        DataObject target = new DataObjectImpl();
        for (String key : source.getAttributeKeys()) {
            Object value = source.get(key);
            if (interpreters.containsKey(key)) {
                值=interpreters.get(key).interpret(value);
            }
            目标.put(key，value);
        }
        返回目标;
    }
}
interface Interpreter {
    对象解释(Object value);
}
class DataObjectImpl extends DataObject {
    private Map<String，Object>属性= new HashMap<>();
    public Set<String> getattributeKeys(){
        返回 this.attributes.keySet();
    }
    public Object get(String key) {
