DataObjectMapper mapper = new DataObjectMapper();
//接下来，创建一个解释器，它将合并first_name和last_name属性
Interpreter nameInterpreter = new Interpreter() {
    public Object interpret(Object value) {
        DataObject source = (DataObject) value;
        String firstName = (String) source.get("first_name");
        String lastName = (String) source.get("last_name");
        return firstName + " " + lastName;
    }
};
//将解释器注册到mapper，指定它应该用于“name”属性
mapper.registerInterpreter("name", nameInterpreter);
//创建具有first_name和last_name属性的源DataObject
DataObject source = new DataObjectImpl();
source.put("first_name", "Eric");
source.put("last_name", "Kingston");
//将源DataObject映射到新的目标DataObject
