}
```
将 `https://your-target-api.example.com/` 替换为目标API的实际URL。
4. 打开 `Startup.cs` 文件，并添加以下using语句：
```csharp
using Microsoft.Extensions.DependencyInjection;
using Yarp.ReverseProxy.Configuration;
```
5. 在 `ConfigureServices` 方法中，添加YARP服务并配置反向代理：
```csharp
public void ConfigureServices(IServiceCollection services)
{
    services.AddControllers();
    services.AddReverseProxy()
        .LoadFromConfig(Configuration.GetSection("ReverseProxy"));
}
```
6. 在 `Configure` 方法中，添加YARP中间件：
```csharp
public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
{
    if (env.IsDevelopment())
    {
        app.UseDeveloperExceptionPage();
    }
    app.UseHttpsRedirection();
    app.UseRouting();
    // 添加YARP中间件
    app.UseReverseProxy();
    app.UseAuthorization();
    app.UseEndpoints(endpoints =>
    {
        endpoints.MapControllers();
    });
}
```
此配置设置YARP以代理所有传入请求到指定的目标API。YARP处理HTTP和WebSocket连接，因此您不需要为WebSocket连接实现单独的逻辑。
请记住，上面的示例不处理HTML内容的资产URL重写。如果您需要重写资产URL，则需要添加自定义中间件以处理和重写HTML内容，然后将其传递给YARP中间件。
有关YARP的更多信息，请参阅官方文档：<https://microsoft.github.io/reverse-proxy/>

这是一个使用 AngleSharp 来进行 ASP.NET Core 应用程序中的 URL 重写并与 YARP 集成的示例：
1. 按照先前的步骤设置使用 YARP 的 ASP.NET Core Web API 项目。
2. 添加 `AngleSharp` NuGet 包：
```java
dotnet add package AngleSharp
```
3. 打开 `Startup.cs` 文件，添加以下 using 语句：
```csharp
using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using AngleSharp.Html.Parser;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
```
4. 为在将 HTML 内容传递给 YARP 中间件之前处理和重写 HTML 内容添加自定义中间件。修改 `Startup.cs` 文件中的 `Configure` 方法：
```csharp
public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
{
    if (env.IsDevelopment())
    {
        app.UseDeveloperExceptionPage();
    }
    app.UseHttpsRedirection();
    app.UseRouting();
    // 添加自定义中间件以进行 URL 重写
    app.Use(async (context, next) =>
    {
        var originalBody = context.Response.Body;
        using var newBody = new MemoryStream();
        context.Response.Body = newBody;
        await next();
        newBody.Seek(0, SeekOrigin.Begin);
        if (context.Response.ContentType != null && context.Response.ContentType.Contains("text/html", StringComparison.OrdinalIgnoreCase))
        {
            var content = await new StreamReader(newBody).ReadToEndAsync();
            var parser = new HtmlParser();
            var document = await parser.ParseDocumentAsync(content);
            // 重写资产 URL 指向代理端点
            foreach (var img in document.Images)
            {
                img.Source = RewriteUrl(img.Source, context);
            }
            foreach (var link in document.QuerySelectorAll("link[href]"))
            {
                link.SetAttribute("href", RewriteUrl(link.GetAttribute("href"), context));
            }
            foreach (var script in document.Scripts)
            {
                script.Source = RewriteUrl(script.Source, context);
            }
            content = document.DocumentElement.OuterHtml;
            context.Response.ContentLength = content.Length;
            await context.Response.WriteAsync(content);
        }
        else
        {
            await newBody.CopyToAsync(originalBody);
        }
    });
    // 添加 YARP 中间件
    app.UseReverseProxy();
    app.UseAuthorization();
    app.UseEndpoints(endpoints =>
    {
        endpoints.MapControllers();
    });
}
private string RewriteUrl(string url, HttpContext context)
{
    if (Uri.IsWellFormedUriString(url, UriKind.Absolute))
    {
        var uriBuilder = new UriBuilder(url)
        {
            Scheme = context.Request.Scheme,
            Host = context.Request.Host.Host,
            Port = context.Request.Host.Port.GetValueOrDefault(-1)
        };
        return uriBuilder.ToString();
    }
    return url;
}
```
此自定义中间件捕获响应体并检查其是否为 HTML 内容。如果是，则使用 AngleSharp 解析 HTML，为图像、CSS 和 JavaScript 文件重写 URL，然后将修改后的内容写回响应。对于非 HTML 内容，它只会复制响应正文而不进行修改。
此示例演示了如何将 YARP 与 AngleSharp 集成以进行 URL 重写。请注意，这是一种简单的实现，可能无法涵盖所有用例。您可能需要调整代码以处理其他类型的资源或特殊情况。

在ASP.NET Core中，您可以使用“LocalHostFiltering”中间件以及授权策略来限制对特定控制器端点的访问仅限于本地请求。以下是实现方法：
1. 打开“Startup.cs”文件并添加以下using语句：
```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
```
2. 修改“Startup.cs”文件中的“ConfigureServices”方法，创建自定义授权策略：
```csharp
public void ConfigureServices(IServiceCollection services)
{
    services.AddControllers();

    // 添加自定义授权策略
    services.AddAuthorization(options =>
    {
        options.AddPolicy("LocalOnly", policy =>
        {
            policy.RequireAssertion(context =>
                context.Resource is HttpContext httpContext && httpContext.Connection.RemoteIpAddress != null &&
                (httpContext.Connection.RemoteIpAddress.Equals(httpContext.Connection.LocalIpAddress) ||
                 httpContext.Connection.RemoteIpAddress.IsLoopback));
        });
    });
}
```
3. 在控制器中，将“[Authorize(Policy = 'LocalOnly')]"属性应用于仅应从本地计算机访问的端点：
```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
namespace MyApi.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class MyController : ControllerBase
    {
        // 此操作可以从任何位置访问
        [HttpGet("public")]
        public IActionResult GetPublicData()
        {
            return Ok("This is public data.");
        }
        // 此操作仅可从本地访问
        [HttpGet("local")]
        [Authorize(Policy = "LocalOnly")]
        public IActionResult GetLocalData()
        {
            return Ok("This is local-only data.");
        }
    }
}
```
现在，“GetLocalData”操作只能从本地计算机访问，而“GetPublicData”操作可以从任何位置访问。
自定义授权策略检查请求的远程IP地址是否与本地IP地址相同，或者远程IP地址是否为环回地址（例如“127.0.0.1”或“::1”）。如果检查通过，则请求被视为本地请求，并允许访问到端点。

使用ACF Pro和Elementor Pro计算“家庭办公室”位置和另一个位置之间的距离，需要执行以下步骤：
1. 首先，创建一个新的自定义字段来存储距离。在WordPress仪表板中，导航到Custom Fields > Field Groups，并编辑与“Locations”自定义文章类型相关联的字段组。添加一个字段，字段类型为“Number”，并给它一个名称，例如“distance_to_home_office”。保存字段组。
2. 接下来，使用Google Maps API计算两个位置之间的距离。您可以通过向主题的`functions.php`文件添加自定义函数或创建自定义插件来实现此目的：
```php
functioncalculate_distance_between_locations($location1_lat, $location1_lng, $location2_lat, $location2_lng){
    $earth_radius=6371; //地球半径，单位为千米
    $lat_diff=deg2rad($location2_lat-$location1_lat);
    $lng_diff=deg2rad($location2_lng-$location1_lng);
    $a=sin($lat_diff/2)*sin($lat_diff/2)+
        cos(deg2rad($location1_lat))*cos(deg2rad($location2_lat))*
        sin($lng_diff/2)*sin($lng_diff/2);
    $c=2*atan2(sqrt($a), sqrt(1-$a));
    $distance=$earth_radius*$c;
    return$distance; //以千米为单位返回距离
}
```
1. 当保存“Locations”文章时自动更新“distance_to_home_office”自定义字段，请将以下代码添加到主题的`functions.php`文件或自定义插件中：
```php
functionupdate_distance_to_home_office($post_id){
    if(get_post_type($post_id)!=='locations'){
        return;
    }
    $home_office=get_page_by_title('Home Office', OBJECT, 'locations');
    if(!$home_office){
        return;
    }
    $home_office_map=get_field('map',$home_office->ID);
    $current_location_map=get_field('map',$post_id);
    if(!$home_office_map||!$current_location_map){
        return;
    }
    $distance=calculate_distance_between_locations(
        $home_office_map['lat'],$home_office_map['lng'],
        $current_location_map['lat'],$current_location_map['lng']
    );
