```
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
public class GravityGun : MonoBehaviour
{
    public float range = 10f; // 重力枪的范围
    public float force = 100f; // 投掷物体的力量
    private Camera mainCamera; // 场景中的主摄像机
    private Rigidbody grabbedObject; // 当前被重力枪抓取的物体
    // 每帧都会调用Update函数
    void Update()
    {
        // 检查是否按下左键
        if (Input.GetMouseButtonDown(0))
        {
            // 检查玩家是否在范围内查看物体
            RaycastHit hit;
            if (Physics.Raycast(mainCamera.transform.position, mainCamera.transform.forward, out hit, range))
            {
                // 抓取物体
                grabbedObject = hit.rigidbody;
                grabbedObject.useGravity = false; // 在抓取物体时禁用重力
                grabbedObject.velocity = Vector3.zero; // 重置物体的速度
            }
        }
        // 检查是否释放左键
        if (Input.GetMouseButtonUp(0) && grabbedObject != null)
        {
            // 投掷物体
            grabbedObject.useGravity = true; // 重新启用重力
            grabbedObject.AddForce(mainCamera.transform.forward * force, ForceMode.Impulse); // 向玩家查看的方向施加力量
            grabbedObject = null; // 重置已抓取的物体
        }
    }
}
```
要使用这个脚本，请将其附加到场景中的GameObject上，并将主摄像机分配到检查器中的`mainCamera`字段中。您可以通过修改相应的`range`和`force`字段来调整重力枪的范围和力量。
