 {
  // Create the cylinder
  GameObject cylinder = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
  // Set the cylinder's position and scale
  cylinder.transform.position = new Vector3(0, 1, 0);
  cylinder.transform.localScale = new Vector3(1, 2, 1);
