  let laterMonthlyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  let earlierYearlyShareOfPool = yearlySnapshot.totalSupply.toBigDecimal().div(yearlySnapshot.poolTotalSupply.toBigDecimal())
  let laterYearlyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  // 计算提供流动性的用户在两个快照之间获得的费用
  let dailyFeesEarned = event.params.totalFees.toBigDecimal().times(laterDailyShareOfPool.minus(earlierDailyShareOfPool))
  let monthlyFeesEarned = event.params.totalFees.toBigDecimal().times(laterMonthlyShareOfPool.minus(earlierMonthlyShareOfPool))
  let yearlyFeesEarned = event.params.totalFees.toBigDecimal().times(laterYearlyShareOfPool.minus(earlierYearlyShareOfPool))
  // 使用新数据更新每日、每月和每年快照
  dailySnapshot.poolTotalSupply = event.params.poolTotalSupply
  dailySnapshot.totalSupply = event.params.totalSupply
  dailySnapshot.totalFees = event.params.totalFees
  dailySnapshot.currentPrice = event.params.currentPrice
  dailySnapshot.feesEarned = dailySnapshot.feesEarned.plus(dailyFeesEarned)
  dailySnapshot.save()
