    };
    initAuth0();
  }, []);
  return (
    <Auth0Context.Provider value={auth0Client}>
      {auth0Client && children}
    </Auth0Context.Provider>
  );
};
export const useAuth0 = () => {
  const auth0Client = React.useContext(Auth0Context);
  return auth0Client;
};
