$stmt = $conn->prepare("SELECT id, name FROM products ORDER BY name LIMIT 20 OFFSET ?");
$stmt->bindValue(1, $offset, PDO::PARAM_INT);
$stmt->execute();
$result = $stmt->fetchAll();
?>
```

