```dart
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:path_provider/path_provider.dart';
import 'package:file_picker/file_picker.dart';
class FolderSelectionPage extends StatefulWidget {
  @override
  _FolderSelectionPageState createState() => _FolderSelectionPageState();
}
class _FolderSelectionPageState extends State<FolderSelectionPage> {
  Directory? _selectedDirectory;
  Future<void> _selectFolder() async {
    try {
      Directory? directory = await FilePicker.platform.getDirectoryPath();
      if (directory != null) {
        setState(() {
          _selectedDirectory = directory;
        });
      }
    } on PlatformException catch (e) {
      print("Error while picking the directory: $e");
    }
  }
  Future<String> _getAppDocumentsDirectoryPath() async {
    Directory appDocumentsDirectory =
        await getApplicationDocumentsDirectory();
    return appDocumentsDirectory.path;
  }
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Folder Selection Page"),
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(
              _selectedDirectory == null
                  ? "No folder selected"
                  : "Selected folder: ${_selectedDirectory!.path}",
              style: TextStyle(fontSize: 18),
            ),
            SizedBox(height: 20),
            ElevatedButton(
              onPressed: _selectFolder,
              child: Text("Select folder"),
            ),
          ],
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () async {
          if (_selectedDirectory != null) {
            String appDocumentsDirectoryPath =
                await _getAppDocumentsDirectoryPath();
            String selectedDirectoryPath = _selectedDirectory!.path;
            Directory selectedDirectory = Directory(selectedDirectoryPath);
            List<FileSystemEntity> files = selectedDirectory.listSync();
            for (FileSystemEntity file in files) {
              String fileName = file.path.split('/').last;
              File sourceFile = File(file.path);
              File destinationFile = File(
                  '$appDocumentsDirectoryPath/$fileName');
              sourceFile.copy(destinationFile.path);
            }
          }
        },
        child: Icon(Icons.save),
      ),
    );
  }
}
```
