    return opportunitiesWithProducts;
  }
  public class OpportunityWithProducts {
    public Id Id { get; set; }
    public String Name { get; set; }
    public List<OpportunityLineItem> OpportunityLineItems { get; set; }
    public Decimal TotalProductValue { get; set; }
  }
}
