  }
  if (col > 0 && !maze[row][col - 1].visited) {
    neighbors.push({ row: row, col: col - 1 });
  }
  return neighbors;
}
// 移除两个单元格之间的墙壁的帮助函数
function removeWall(row1, col1, row2, col2) {
  if (row1 > row2) {
    maze[row1][col1].top = false;
    maze[row2][col2].bottom = false;
  } else if (row1 < row2) {
    maze[row1][col1].bottom = false;
    maze[row2][col2].top = false;
  } else if (col1 > col2) {
    maze[row1][col1].left = false;
    maze[row2][col2].right = false;
  } else if (col1 < col2) {
    maze[row1][col1].right = false;
    maze[row2][col2].left = false;
  }
}
