使用JavaScript从Infor Visual ERP中提取工票信息，您需要使用基于SOAP的Infor Visual ERP API。下面是一些示例代码，演示了如何使用API检索工票信息：
```javascript
// 初始化SOAP客户端
var soap = require('soap');
var url = 'https://[your-visual-url]/inforionapitest.asmx?WSDL';
var client = null;
soap.createClient(url, function(err, soapClient) {
    if (err) {
        console.error(err);
    } else {
        client = soapClient;
        console.log('SOAP client initialized');
    }
});
// 定义工票查询参数
var query = {
    'TicketCriteria': {
        'OrderByField': 'LaborTicketNumber',
        'PageNumber': 1,
        'PageSize': 10,
        'SortDirection': 'Ascending',
        'TicketNumber': '',
        'TicketStatus': 'All',
        'WorkCenter': ''
    }
};
// 检索工票信息
client.GetLaborTickets(query, function(err, result) {
    if (err) {
        console.error(err);
    } else {
        console.log('Retrieved labor tickets:');
        console.log(result);
    }
});
