以下是一段实现您所描述要求的 Python 函数的代码：

```python
from datetime import datetime, timedelta
def format_date(target_date: datetime) -> str:
    now = datetime.now()
    time_diff = target_date - now
    abs_diff = abs(time_diff)
    one_hour = timedelta(hours=1)
    one_day = timedelta(days=1)
    yesterday = now - one_day
    tomorrow = now + one_day
    if abs_diff < one_hour:
        if time_diff > timedelta(0):
            return f"in {abs_diff.seconds // 60} minutes"
        else:
            return f"{abs_diff.seconds // 60} minutes ago"
    elif abs_diff < one_day:
        if target_date.date() == now.date():
            if time_diff > timedelta(0):
                return f"in {abs_diff.seconds // 3600} hours at {target_date.strftime('%I:%M %p')}"
            else:
                return f"{abs_diff.seconds // 3600} hours ago at {target_date.strftime('%I:%M %p')}"
        elif target_date.date() == yesterday.date():
            return f"yesterday at {target_date.strftime('%I:%M %p')}"
        elif target_date.date() == tomorrow.date():
            return f"tomorrow at {target_date.strftime('%I:%M %p')}"
    else:
        if abs_diff < timedelta(days=2) + timedelta(hours=6):
            if time_diff > timedelta(0):
                if target_date.hour < 12:
                    return f"tomorrow morning at {target_date.strftime('%I:%M %p')}"
                elif target_date.hour < 18:
                    return f"tomorrow afternoon at {target_date.strftime('%I:%M %p')}"
                else:
                    return f"tomorrow evening at {target_date.strftime('%I:%M %p')}"
            else:
                if target_date.hour < 12:
