            {
                Console.Write(item + " ");
            }
            Console.WriteLine();
        }
        static async Task SortArrayAsync(int[] arr)
        {
            await Task.Run(() => BubbleSort(arr));
        }
        static void BubbleSort(int[] arr)
        {
            int n = arr.Length;
            for (int i = 0; i < n - 1; i++)
            {
                for (int j = 0; j < n - i - 1; j++)
                {
                    if (arr[j] > arr[j + 1])
